import "dotenv/config";
import fs from "fs";
import path from "path";
import readline from "readline";
import { MongoClient, type Collection } from "mongodb";
import { fetchAllTracks } from "./fetchTracks";
import { generateVibeDescriptions } from "./generateVibeDescriptions";
import { generateEmbeddings } from "./generateEmbeddings";

const MONGODB_URI = process.env.MONGODB_URI;
const MONGODB_DATABASE = process.env.MONGODB_DATABASE ?? "song_vibe_search";
const COLLECTION_NAME = "songs";
const VECTOR_INDEX_NAME = "vibe_vector_index";
// Pre-built dataset — generated by running the full pipeline once and exporting.
// If this file exists, the seed script uses it directly and skips the Gemini/Voyage AI steps.
const DATA_FILE = path.resolve(__dirname, "data/songs.json");

if (!MONGODB_URI) {
  throw new Error(
    "Missing MONGODB_URI in environment. Ensure that you have created a .env file and added your connection string."
  );
}

interface SongDocument {
  title: string;
  artist: string;
  album: string;
  fma_track_id: number;
  fma_url: string;
  play_count: number;
  genre_top: string;
  genres: string[];
  vibe_description: string;
  embedding: number[];
  seeded_at: Date;
}

function confirm(message: string): Promise<boolean> {
  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
  return new Promise((resolve) => {
    rl.question(`${message} [Y/N] `, (answer) => {
      rl.close();
      resolve(answer.trim().toLowerCase() === "y");
    });
  });
}

async function getSongsCollection(
  client: MongoClient
): Promise<Collection<SongDocument>> {
  return client
    .db(MONGODB_DATABASE)
    .collection<SongDocument>(COLLECTION_NAME);
}

async function createVectorSearchIndex(
  collection: Collection<SongDocument>
): Promise<void> {
  console.log("\nCreating Vector Search index...");

  try {
    await collection.createSearchIndex({
      name: VECTOR_INDEX_NAME,
      type: "vectorSearch",
      definition: {
        fields: [
          {
            type: "vector",
            path: "embedding",
            numDimensions: 512,
            similarity: "cosine",
          },
        ],
      },
    });
    console.log(`  Index "${VECTOR_INDEX_NAME}" created. It may take a moment to become active.`);
  } catch (err: any) {
    if (err?.message?.includes("already exists")) {
      console.log(`  Index "${VECTOR_INDEX_NAME}" already exists — skipping.`);
    } else {
      throw err;
    }
  }
}

async function main(): Promise<void> {
  console.log("=== Song Vibe Search - Seeding Pipeline ===\n");
  console.log(`Target database  : ${MONGODB_DATABASE}`);
  console.log(`Target collection: ${COLLECTION_NAME}`);

  const client = new MongoClient(MONGODB_URI!, { appName: "devrel-github-javascript-music-recommender-seed" });

  try {
    // Step 1 - Connect to MongoDB first so we can check whether seeding
    // has already been done before touching the CSV or calling Voyage AI.
    console.log("\nConnecting to MongoDB...");
    await client.connect();
    console.log("Connected.");

    const collection = await getSongsCollection(client);

    // Step 2 - Check if the collection already has data.
    // If it does, skip the entire data pipeline to avoid re-parsing the CSV
    // and making unnecessary Voyage AI API calls.
    const existingCount = await collection.countDocuments();

    if (existingCount > 0) {
      console.log(`\nCollection already contains ${existingCount} documents — skipping data pipeline.`);
    } else if (fs.existsSync(DATA_FILE)) {
      // Fast path: pre-built dataset found — skip Gemini and Voyage AI entirely.
      console.log(`\nPre-built dataset found. Loading from ${DATA_FILE}...`);
      const raw = JSON.parse(
        fs.readFileSync(DATA_FILE, "utf-8")
      ) as Omit<SongDocument, "seeded_at">[];
      const documents: SongDocument[] = raw.map((doc) => ({
        ...doc,
        seeded_at: new Date(),
      }));
      console.log(`\nInserting ${documents.length} documents into MongoDB...`);
      await collection.insertMany(documents);
      console.log("  Done.");

    } else {
      // Full pipeline: fetch CSV → Gemini → Voyage AI → insert.
      // Step 3 - Parse the FMA metadata CSV.
      const rawTracks = await fetchAllTracks();

      if (rawTracks.length === 0) {
        console.error("\nNo tracks loaded — check that fma_metadata/tracks.csv exists and is readable.");
        process.exit(1);
      }

      const proceedGemini = await confirm(
        "\nReady to generate vibe descriptions using your Gemini key.\n" +
        "This will use tokens and may incur charges if your free tier limit is exceeded. Proceed?"
      );
      if (!proceedGemini) {
        console.log("Aborted.");
        process.exit(0);
      }

      // Step 4 - Generate vibe descriptions via Gemini.
      const tracksWithVibes = await generateVibeDescriptions(rawTracks);

      // Step 5 - Confirm before calling Voyage AI.
      const proceedVoyage = await confirm(
        "\nReady to generate embeddings using your Voyage AI key.\n" +
        "This will use tokens and may incur charges if your free tier limit is exceeded. Proceed?"
      );
      if (!proceedVoyage) {
        console.log("Aborted.");
        process.exit(0);
      }

      const tracksWithEmbeddings = await generateEmbeddings(tracksWithVibes);

      if (tracksWithEmbeddings.length === 0) {
        console.error("\nNo embeddings generated — check your VOYAGE_API_KEY.");
        process.exit(1);
      }

      // Step 6 - Insert into MongoDB.
      const documents = tracksWithEmbeddings.map((track) => ({
        ...track,
        seeded_at: new Date(),
      }));

      console.log(`\nInserting ${documents.length} documents into MongoDB...`);
      await collection.insertMany(documents);
      console.log("  Done.");
    }

    // Step 7 - Create the Vector Search index.
    // Always runs — safe to call when the index already exists.
    await createVectorSearchIndex(collection);

    const finalCount = await collection.countDocuments();
    console.log(`\n=== Seeding complete ===`);
    console.log(`Documents in '${COLLECTION_NAME}': ${finalCount}`);

  } catch (err) {
    console.error("\nSeeding failed:", err);
    process.exit(1);
  } finally {
    await client.close();
    console.log("\nMongoDB connection closed.");
  }
}

main();